from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    color = min((v for v in counts if v != background), key=lambda v: counts[v])
    cells = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == color]
    r0, c0 = min(r for r, c in cells), min(c for r, c in cells)
    shape = [(r-r0, c-c0) for r, c in cells]
    sh = max(r for r, c in shape) + 1
    sw = max(c for r, c in shape) + 1
    out = [row[:] for row in grid]
    for r in range(h-sh+1):
        for c in range(w-sw+1):
            if all(grid[r+dr][c+dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    out[r+dr][c+dc] = color
    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))", "exit_code": 0, "error": null}
